def compare_decimaux(a, b):
    # a et b sont des chaînes comme "3,14" ou "2,5"
    if ',' in a:
        ent_a, dec_a = a.split(',')
    else:
        ent_a, dec_a = a, ''
    if ',' in b:
        ent_b, dec_b = b.split(',')
    else:
        ent_b, dec_b = b, ''
    # aligner les parties décimales
    max_len = max(len(dec_a), len(dec_b))
    dec_a = dec_a.ljust(max_len, '0')
    dec_b = dec_b.ljust(max_len, '0')
    # comparer parties entières
    if int(ent_a) < int(ent_b):
        return -1
    elif int(ent_a) > int(ent_b):
        return 1
    # comparer parties décimales chiffre par chiffre
    for da, db in zip(dec_a, dec_b):
        if da < db:
            return -1
        elif da > db:
            return 1
    return 0
